<script setup>
import {onMounted,ref,computed,watch} from 'vue';
import {ElMessage} from 'element-plus';
import {apiClient} from '../../utils/api.js';
import {materialBindings,categoryKey} from '../../../../src/shared/workflow-materials.js';
import WorkflowMaterialLibrary from './WorkflowMaterialLibrary.vue';
import WorkflowValuePreview from './WorkflowValuePreview.vue';
const props=defineProps({modelValue:{type:Array,default:()=>[]},label:{type:String,default:'引用生产资料'},imageReferences:{type:Boolean,default:true},direct:Boolean,category:{type:Object,default:()=>({})},fitments:{type:Array,default:()=>[]},autoSelect:Boolean,disabled:Boolean}),emit=defineEmits(['update:modelValue']);
const records=ref([]),open=ref(false),loading=ref(false),error=ref('');let sequence=0;
const selected=computed(()=>props.modelValue.map(ref=>ref.id));
const selectedRecords=computed(()=>props.modelValue.map(ref=>({ref,record:records.value.find(r=>r.id===ref.id)})).filter(x=>x.record));
const stale=computed(()=>!loading.value&&props.modelValue.filter(ref=>!records.value.some(r=>r.id===ref.id&&r.revision===ref.revision)));
function remember(record){records.value=[...records.value.filter(r=>r.id!==record.id),record];}
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const results=await Promise.all(props.modelValue.map(ref=>apiClient.get(`/api/product-workflows/${ref.kind==='key_model'?'key-models':'materials'}?id=${encodeURIComponent(ref.id)}`,{noCache:true}).catch(e=>{if(e.status!==404)throw e;return null;})));if(seq!==sequence)return;records.value=results.filter(Boolean);if(props.autoSelect&&!props.modelValue.length&&props.fitments.length){const matches=await apiClient.get('/api/product-workflows/key-model-matches?'+new URLSearchParams({fitments:JSON.stringify(props.fitments),category:categoryKey(props.category)}),{noCache:true});if(seq===sequence&&matches.length===1&&!props.disabled)choose(matches[0]);}}catch(e){if(seq===sequence){error.value=e.message;ElMessage.error(e.message);}}finally{if(seq===sequence)loading.value=false;}}
function choose(record){if(props.direct&&!record.payload.images?.length)return ElMessage.warning('请选择带图片的成品资料');remember(record);const ref={id:record.id,kind:record.kind,revision:record.revision,...(props.direct?{imageIndex:0}:{})};emit('update:modelValue',props.direct?[ref]:[...props.modelValue.filter(r=>r.id!==record.id),ref]);if(props.direct)open.value=false;}
function remove(id){emit('update:modelValue',props.modelValue.filter(ref=>ref.id!==id));}
function refresh(){emit('update:modelValue',props.modelValue.filter(ref=>records.value.some(r=>r.id===ref.id&&!r.payload.archived)).map(ref=>({...ref,revision:records.value.find(r=>r.id===ref.id).revision})));}
function chooseIndex(id,index){emit('update:modelValue',props.modelValue.map(ref=>ref.id===id?{...ref,imageIndex:index}:ref));}
watch(()=>JSON.stringify(props.modelValue),load);onMounted(load);
</script>
<template><div class="material-references" v-loading="loading"><div class="references-head"><strong>{{ label }} <el-tag size="small">已引用 {{ modelValue.length }} 份</el-tag></strong><el-button type="primary" plain :disabled="disabled" @click="open=true">从资料库选择 / 新增</el-button></div><p class="reference-hint">{{ direct?'选一张资料原图直接使用，不调用 AI。':imageReferences?'引用图片及说明，作为当前节点的生成参考。':'只把资料文字提供给文本模型，图片可预览核对。' }}</p><div v-if="!modelValue.length" class="reference-empty">尚未引用资料，点击右侧按钮按类目、品牌、型号搜索</div><div class="selected-grid"><article v-for="{ref,record} in selectedRecords" :key="ref.id" class="selected-material"><div class="references-head"><strong>{{ record.name }}</strong><el-button link type="danger" :disabled="disabled" @click="remove(ref.id)">移除引用</el-button></div><small>{{ record.payload.listingCategory?.name||'跨类目通用资料' }}</small><small>{{ materialBindings(record.payload).map(b=>`${b.brand} · ${b.models.join('、')}`).join('；')||'未限制品牌型号' }}</small><el-tag v-if="record.payload.reviewStatus==='pending'" size="small" type="warning">适配待核对</el-tag><WorkflowValuePreview :value="direct?[record.payload.images[ref.imageIndex||0]]:record.payload.images" format="images"/><el-radio-group v-if="direct&&record.payload.images.length>1" :model-value="ref.imageIndex||0" :disabled="disabled" @change="chooseIndex(ref.id,$event)"><el-radio-button v-for="(_,i) in record.payload.images" :key="i" :value="i">图 {{ i+1 }}</el-radio-button></el-radio-group><WorkflowValuePreview v-if="record.payload.notes" :value="record.payload.notes" label="引用文字"/></article></div><el-alert v-if="stale.length&&!error" type="warning" :closable="false" title="部分引用已更新或不可用，请更新引用，或移除后重新选择。"><el-button :disabled="disabled" link @click="refresh">更新引用</el-button><el-button v-for="ref in stale" :key="ref.id" :disabled="disabled" link @click="remove(ref.id)">移除失效引用</el-button></el-alert><el-dialog v-model="open" title="选择生产资料" width="min(1250px,94vw)" top="3vh" append-to-body><WorkflowMaterialLibrary v-if="open" selectable :selected-ids="selected" :category="category" :seed="{bindings:fitments.reduce((rows,f)=>{let b=rows.find(b=>b.brand===f.brand);if(!b){b={brand:f.brand,models:[]};rows.push(b);}b.models.push(f.model);return rows;},[])}" @select="choose" @saved="load"/><template #footer><el-button type="primary" @click="open=false">完成选择</el-button></template></el-dialog></div></template>
<style scoped>.references-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:8px}.references-head strong{font-size:13px}.reference-hint,small{font-size:12px;line-height:1.7;color:var(--el-text-color-secondary)}small{display:block;margin:4px 0}.material-references{margin:12px 0}.reference-empty{padding:14px;border:1px dashed var(--el-border-color);border-radius:6px;color:var(--el-text-color-secondary);font-size:12px}.selected-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:12px}.selected-material{padding:12px;border:1px solid var(--el-border-color-lighter);border-radius:8px;min-width:0}.selected-material .value-preview{margin-top:10px}.selected-material :deep(.preview-images .el-image){width:82px;height:110px}.selected-material :deep(.value-preview p){max-height:96px}@media(max-width:650px){.references-head{flex-wrap:wrap}}
</style>
